    } */
}

vec solve (long long n, vec v, int at) {
  if (n == 0) return v;
  int w = val (n / k);
  v = solve (n / k, v, at + 1);
  for (int i = 0; i < n % k; i++) {
    v = mult (E[at][(w + i) % k], v);
  }
  return v;
}

int main() {
  scanf ("%lld %lld", &n, &k);
  for (int i = 0; i < k; i++) {
    cur.a[i] = 1;
    for (int j = 0; j < k; j++) {
      for (int l = 0; l < k; l++) {
    if (j == l) {
      M[i].a[j][l] = 1;
      MI[i].a[j][l] = 1;
    }
    else if (j == i) {
      M[i].a[j][l] = 1;
      MI[i].a[j][l] = -1;
    }
    else {
      M[i].a[j][l] = 0;
      MI[i].a[j][l] = 0;
    }
      }
    }
  }
  pre_comp();
  cur = solve (n, cur, 0);
  //  printf ("%lld %lld\n", cur.a[0], cur.a[1]);
  long long tot = 0;
  for (int i = 0; i < k; i++) {
    tot += cur.a[i];
  }
  tot--;
  tot %= MOD;
  if (tot < 0) tot += MOD;
  while (tot % (k - 1) != 0) {
